IF  NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'GENHTOC') AND type in (N'U'))
BEGIN
CREATE TABLE [dbo].[GENHTOC](
	[FLDID] [varchar](10) NOT NULL,
	[TOC] [varchar](10) NOT NULL,
	[FLDCOM] [bit] NULL,
	[FLDCOMA] [bit] NULL,
 CONSTRAINT [I_GENHTOC] PRIMARY KEY CLUSTERED 
(
	[FLDID] ASC,
	[TOC] ASC
)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
) ON [PRIMARY]

SET ANSI_PADDING OFF

ALTER TABLE [dbo].[GENHTOC]  WITH CHECK ADD  CONSTRAINT [FK_GENHTOC_GENHTAB] FOREIGN KEY([FLDID])
REFERENCES [dbo].[GENHTAB] ([FLDID])
ON UPDATE CASCADE
ON DELETE CASCADE

ALTER TABLE [dbo].[GENHTOC] CHECK CONSTRAINT [FK_GENHTOC_GENHTAB]

end
GO



DROP FUNCTION FN_GENHTAB 
GO
CREATE FUNCTION FN_GENHTAB (@P_FLDID as varchar(10), @P_SEGMENT as varchar(10), @P_TOC as varchar(10))     
RETURNS Table
AS RETURN (

Select 
G1.FLDTAB, 
Case 
when G1.FLDCOM=1 Then G1.FLDCOM 
WHen coalesce(G2.FLDCOM, cast(0 as Bit))=1 Then coalesce(G2.FLDCOM, cast(0 as Bit))
WHen coalesce(G3.FLDCOM, cast(0 as Bit))=1 Then coalesce(G3.FLDCOM, cast(0 as Bit))
Else cast(0 as Bit) End as FLDCOM,
Case 
when G1.FLDCOMA=1 Then G1.FLDCOMA 
WHen coalesce(G2.FLDCOMA, cast(0 as Bit))=1 Then coalesce(G2.FLDCOMA, cast(0 as Bit))
WHen coalesce(G3.FLDCOMA, cast(0 as Bit))=1 Then coalesce(G3.FLDCOMA, cast(0 as Bit))
Else cast(0 as Bit) End as FLDCOMA,
G1.FLDDFORMAT,
G1.FLDIFORMAT,
G1.FLDTYPE,
G1.SUBLINKF, 
G1.FLDSEARCH,
G1.FLDCRITERIA,
G1.FLDCHGINF,
G1.FLDLOWER,
G1.FLDUPPER,
G1.FLDREGEX,
G1.FLDFUNC,
G1.FLDMAP,
G1.FLDENCRYPTF,
G1.FLDID1,
G1.FLDVALUATION, 
G1.SACCREG
from GenHTab G1
Outer Apply (Select Top 1 G2.FLDCOM, G2.FLDCOMA from GenHSegment G2 Where G2.FLDID=G1.FLDID and (G2.SEGMENT='<All>' or G2.SEGMENT=@P_SEGMENT)) G2
Outer Apply (Select Top 1 G3.FLDCOM, G3.FLDCOMA from GenHTOC G3 Where G3.FLDID=G1.FLDID and (G3.TOC='<All>' or G3.TOC=@P_TOC)) G3
Where G1.FLDID=@P_FLDID
)



GO

