DROP PROCEDURE QTOI_GENHTAB 
GO
CREATE PROCEDURE QTOI_GENHTAB (@P_TOI AS VARCHAR(10), @P_NOC as VARCHAR(10)='', @P_SEGMENT as VARCHAR(10)='', @P_TOC as VARCHAR(10)='')      
AS      
SELECT  TOP 1      
TOI.TOI, TOI.DESCRIPTION, 
