COB.FLDID13, COB.FLDTAG13, GENHTAB_13.FLDTAB AS FLDTAB13, GENHTAB_13.FLDCOM AS FLDCOM13, GENHTAB_13.FLDDFORMAT AS FLDDFORMAT13, GENHTAB_13.FLDIFORMAT AS FLDIFORMAT13, GENHTAB_13.FLDTYPE AS FLDTYPE13, GENHTAB_13.SUBLINKF AS SUBLINKF13,  GENHTAB_13.FLDSEARCH AS FLDSEARCH13, GENHTAB_13.FLDCRITERIA AS FLDCRITERIA13, GENHTAB_13.FLDENCRYPTF as FLDENCRYPTF13, GENHTAB_13.FLDLOWER as FLDLOWER13, GENHTAB_13.FLDUPPER as FLDUPPER13, GENHTAB_13.FLDREGEX as FLDREGEX13, GENHTAB_13.FLDFUNC as FLDFUNC13, CASE WHEN GENHTAB_13.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF13,
COB.FLDID14, COB.FLDTAG14, GENHTAB_14.FLDTAB AS FLDTAB14, GENHTAB_14.FLDCOM AS FLDCOM14, GENHTAB_14.FLDDFORMAT AS FLDDFORMAT14, GENHTAB_14.FLDIFORMAT AS FLDIFORMAT14, GENHTAB_14.FLDTYPE AS FLDTYPE14, GENHTAB_14.SUBLINKF AS SUBLINKF14,  GENHTAB_14.FLDSEARCH AS FLDSEARCH14, GENHTAB_14.FLDCRITERIA AS FLDCRITERIA14, GENHTAB_14.FLDENCRYPTF as FLDENCRYPTF14, GENHTAB_14.FLDLOWER as FLDLOWER14, GENHTAB_14.FLDUPPER as FLDUPPER14, GENHTAB_14.FLDREGEX as FLDREGEX14, GENHTAB_14.FLDFUNC as FLDFUNC14, CASE WHEN GENHTAB_14.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF14,
COB.FLDID15, COB.FLDTAG15, GENHTAB_15.FLDTAB AS FLDTAB15, GENHTAB_15.FLDCOM AS FLDCOM15, GENHTAB_15.FLDDFORMAT AS FLDDFORMAT15, GENHTAB_15.FLDIFORMAT AS FLDIFORMAT15, GENHTAB_15.FLDTYPE AS FLDTYPE15, GENHTAB_15.SUBLINKF AS SUBLINKF15,  GENHTAB_15.FLDSEARCH AS FLDSEARCH15, GENHTAB_15.FLDCRITERIA AS FLDCRITERIA15, GENHTAB_15.FLDENCRYPTF as FLDENCRYPTF15, GENHTAB_15.FLDLOWER as FLDLOWER15, GENHTAB_15.FLDUPPER as FLDUPPER15, GENHTAB_15.FLDREGEX as FLDREGEX15, GENHTAB_15.FLDFUNC as FLDFUNC15, CASE WHEN GENHTAB_15.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF15
